class_name S05Replication
extends S03Replication
## Adds scoped fire/current-car/live-event methods to the existing S03 RPC writer.

signal fire_result(reason: String)

const MAX_FIRE_BYTES: int = 512
const FIRE_BURST: int = 4
const FIRE_RATE: float = 4.0
const MAX_CUT_BYTES: int = 8192

var fire_rates: Dictionary = {}
var max_car_bytes: int = 0
var max_fire_bytes: int = 0
var live_received: int = 0
var duplicate_live_rejected: int = 0


## Sends only primitive fire intent; target, damage and ShotId allocation stay on host.
func send_fire(envelope: Variant) -> void:
	_fire.rpc_id(1, envelope)


## Resolves sender before allocating rate state or validating admitted fire intent.
@rpc("any_peer", "call_remote", "reliable", 0)
func _fire(envelope: Variant) -> void:
	if not multiplayer.is_server():
		return

	var peer: int = multiplayer.get_remote_sender_id()
	var participant: int = int(resolve_participant.call(peer))
	if participant == 0:
		return

	var bytes: int = var_to_bytes(envelope).size()
	max_fire_bytes = maxi(max_fire_bytes, bytes)
	var reason: String = "RATE_LIMIT"
	if _permit(peer):
		reason = "INVALID"
		if bytes <= MAX_FIRE_BYTES:
			reason = (match_state as S05Match).submit_fire(participant, envelope)

	_fire_result.rpc_id(peer, reason)


## Bounds requests to one token bucket per inherited sender mapping and no queue.
func _permit(peer: int) -> bool:
	if not fire_rates.has(peer):
		fire_rates[peer] = {"tokens": float(FIRE_BURST), "time": Time.get_ticks_msec()}

	var bucket: Dictionary = fire_rates[peer]
	var now: int = Time.get_ticks_msec()
	bucket.tokens = minf(FIRE_BURST, bucket.tokens + (now - bucket.time) * FIRE_RATE / 1000.0)
	bucket.time = now
	if bucket.tokens < 1.0:
		return false

	bucket.tokens -= 1.0
	return true


## Reports rejection/acceptance without creating another authoritative state writer.
@rpc("authority", "call_remote", "reliable", 0)
func _fire_result(reason: String) -> void:
	fire_result.emit(reason)


## Publishes a bounded complete current cut only to already admitted participants.
func publish_cars(cut: Dictionary) -> void:
	max_car_bytes = maxi(max_car_bytes, JSON.stringify(cut).to_utf8_buffer().size())
	assert(max_car_bytes <= MAX_CUT_BYTES)
	for peer: int in multiplayer.get_peers():
		var participant: int = int(resolve_participant.call(peer))
		if match_state.bindings.has(participant) and match_state.bindings[participant].admitted:
			_cars.rpc_id(peer, cut)


## Applies current life/collision rows atomically on the sole reliable state stream.
@rpc("authority", "call_remote", "reliable", 1)
func _cars(cut: Dictionary) -> void:
	if JSON.stringify(cut).to_utf8_buffer().size() <= MAX_CUT_BYTES:
		(match_state as S05Match).apply_cars(cut)


## Publishes the live event twice deliberately to exercise actual remote deduplication.
func publish_blast(event: Dictionary) -> void:
	for peer: int in multiplayer.get_peers():
		var participant: int = int(resolve_participant.call(peer))
		if match_state.bindings.has(participant) and match_state.bindings[participant].admitted:
			_blast.rpc_id(peer, event)
			_blast.rpc_id(peer, event)


## Consumes bounded live receipts only after current-state installation; no future queue.
@rpc("authority", "call_remote", "reliable", 1)
func _blast(event: Dictionary) -> void:
	if var_to_bytes(event).size() > MAX_FIRE_BYTES:
		return

	var state: S05Match = match_state as S05Match
	if state.effects.consume(event, state.damage.revision, state.damage.tick):
		live_received += 1
	else:
		duplicate_live_rejected += 1


## Drops disconnected request buckets alongside inherited baseline/held work.
func forget(peer: int) -> void:
	fire_rates.erase(peer)
	super.forget(peer)


## Clears pending scoped network state with the inherited attempt lifecycle.
func clear() -> void:
	fire_rates.clear()
	super.clear()

class_name S05Match
extends S03Match
## Reuses S03 marker admission; damage rows have one separate scoped owner.

@onready var damage: S05Damage = $Damage
@onready var effects: S05Presentation = $Presentation


## Establishes passive roles before any saved car descendant can run ready callbacks.
func _enter_tree() -> void:
	for body: S05Car in $Cars.get_children():
		body.configure(false)


## Injects saved cars and connects local live presentation through the match coordinator.
func _ready() -> void:
	var saved: Array[S05Car] = []
	for body: S05Car in $Cars.get_children():
		saved.append(body)

	damage.bind_bodies(saved)
	damage.exploded.connect(_present)


## Advances the same sole gameplay owner only on authoritative physics ticks.
func _physics_process(delta: float) -> void:
	super._physics_process(delta)
	if authoritative:
		damage.advance()
		effects.advance(damage.tick)


## Adds bounded lifetime shooter registration alongside inherited provisional markers.
func prepare_initial(participant: int) -> int:
	if damage.session_id.is_empty():
		damage.begin(authoritative, session_id)
		effects.begin(session_id)

	var entity: int = super.prepare_initial(participant)
	assert(damage.register_shooter(entity, 1), "S05 lifetime shooter capacity exhausted")
	return entity


## Extends the existing immutable S03 cut with current car/life state, never events.
func baseline(participant: int, baseline_id: int) -> Dictionary:
	var data: Dictionary = super.baseline(participant, baseline_id)
	data["cars"] = damage.cut()
	return data


## Preflights car dependencies before inherited marker mutation and disabled rig binding.
func apply_baseline(data: Dictionary) -> bool:
	if not data.get("cars") is Dictionary:
		return false

	damage.session_id = session_id
	if not damage.valid_cut(data.cars):
		return false

	var cars: Dictionary = data.cars.duplicate(true)
	if not super.apply_baseline(data):
		return false

	damage.begin(false, session_id)
	effects.begin(session_id)
	return damage.apply_cut(cars, true)


## Validates admitted sender-owned primitive fire intent before host-only shot resolution.
func submit_fire(participant: int, envelope: Variant) -> String:
	if not authoritative or not bindings.has(participant) or not bindings[participant].admitted:
		return "NOT_ADMITTED"
	if not envelope is Dictionary or envelope.size() != 3:
		return "INVALID"
	if not envelope.get("sequence") is int or envelope.get("fire") != true:
		return "INVALID"
	if not envelope.get("fire") is bool or not envelope.get("context") is Dictionary:
		return "INVALID"
	if envelope.context != context(participant):
		return "STALE_CONTEXT"

	var binding: Dictionary = bindings[participant]
	return damage.resolve_shot({"session": session_id, "match": 1, "shooter": binding.entity,
		"generation": binding.generation, "sequence": envelope.sequence}, S05Damage.CAR_ID_START)


## Applies only current reliable car rows; marker movement has no car lifecycle writer.
func apply_cars(cut: Dictionary) -> bool:
	return damage.apply_cut(cut)


## Consumes live events through the presentation owner after their durable car dependency.
func _present(event: Dictionary) -> void:
	effects.consume(event, damage.revision, damage.tick)


## Removes shooter control while preserving shot rejection history until session teardown.
func rollback(participant: int) -> void:
	if bindings.has(participant):
		damage.retire_shooter(bindings[participant].entity)

	super.rollback(participant)


## Clears scoped jobs/effects before the inherited session close becomes observable.
func clear() -> void:
	damage.clear()
	effects.clear()
	super.clear()
